/* eslint-disable max-len, max-params */

'use strict';

// MODULES //

var isLayout = require( '@stdlib/blas/base/assert/is-layout' );
var format = require( '@stdlib/string/format' );
var isOperationSide = require( '@stdlib/blas/base/assert/is-operation-side' );
var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major-string' );
var isMatrixTranspose = require( '@stdlib/blas/base/assert/is-transpose-operation' );
var max = require( '@stdlib/math/base/special/fast/max' );
var min = require( '@stdlib/math/base/special/min' );
var base = require( './base.js' );


// MAIN //

/**
* Multiplies a general matrix by the orthogonal matrix from a bi-diagonal reduction determined by `DGEBRD`.
*
* ## Notes
*
* -   `Q` and `P^T` are the orthogonal matrices determined by `DGEBRD` when reducing a real matrix `A` to bi-diagonal form, `A = Q * B * P^T`.
*
* -   If VECT = 'Q', `DORMBR` overwrites the general real `M` by `N` matrix `C` with,
*
*     -   `Q * C`  if SIDE = 'left' and TRANS = 'no-transpose', or
*     -   `Q^T * C`  if SIDE = 'left' and TRANS = 'transpose', or
*     -   `C * Q`  if SIDE = 'right' and TRANS = 'no-transpose', or
*     -   `C * Q^T`  if SIDE = 'right' and TRANS = 'transpose'.
*
* -   If VECT = 'P', `DORMBR` overwrites the general real `M` by `N` matrix `C` with,
*
*     -   `P * C`  if SIDE = 'left' and TRANS = 'no-transpose', or
*     -   `P^T * C`  if SIDE = 'left' and TRANS = 'transpose', or
*     -   `C * P`  if SIDE = 'right' and TRANS = 'no-transpose', or
*     -   `C * P^T`  if SIDE = 'right' and TRANS = 'transpose'.
*
* -   If SIDE = 'left', `LWORK >= max(1,N)`.
*
* -   If SIDE = 'right', `LWORK >= max(1,M)`.
*
* -   For optimum performance, `LWORK >= N*NB` if SIDE = 'left', and `LWORK >= M*NB` if SIDE = 'right', where `NB` is the optimal blocksize.
*
* -   If `LWORK = -1`, then a workspace query is assumed; the routine only calculates the optimal size of the `WORK` array and returns this value as the first entry of the `WORK` array.
*
* @param {string} order - storage layout
* @param {string} vect - specifies whether the matrix `Q` or the matrix `P` is applied
* @param {string} side - specifies the side of multiplication with `C`
* @param {string} trans - `'no-transpose'` for `Q` or `P`, `'transpose'` for `Q^T` or `P^T`
* @param {NonNegativeInteger} M - number of rows of `C`
* @param {NonNegativeInteger} N - number of columns of `C`
* @param {NonNegativeInteger} K - number of elementary reflectors
* @param {Float64Array} A - reflector vectors from `DGEBRD`
* @param {integer} LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param {Float64Array} TAU - scalar factors of reflectors
* @param {Float64Array} C - input/output matrix
* @param {integer} LDC - stride of the first dimension of `C` (a.k.a., leading dimension of the matrix `C`)
* @param {Float64Array} WORK - workspace array
* @param {NonNegativeInteger} LWORK - dimension of the array `WORK`
* @throws {TypeError} first argument must be a valid order
* @throws {TypeError} second argument must be either `'Q'` or `'P'`
* @throws {TypeError} third argument must be a valid operation side
* @throws {TypeError} fourth argument must be a valid transpose operation
* @throws {RangeError} fifth argument must be a nonnegative integer
* @throws {RangeError} sixth argument must be a nonnegative integer
* @throws {RangeError} seventh argument must be a nonnegative integer
* @throws {RangeError} ninth argument must be a valid `LDA` value
* @throws {RangeError} twelfth argument must be a valid `LDC` value
* @throws {RangeError} fourteenth argument must be a valid `LWORK` value
* @returns {integer} status code (0 if successful)
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1, 0, 0 ] );
* var TAU = new Float64Array( [ 2 ] );
* var C = new Float64Array( [ 1, 3, 5, 2, 4, 6 ] );
* var WORK = new Float64Array( 3 );
*
* var info = dormbr( 'row-major', 'Q', 'left', 'no-transpose', 2, 3, 1, A, 2, TAU, C, 3, WORK, 3 );
* // returns 0
* // C => <Float64Array>[ -1, -3, -5, 2, 4, 6 ]
* // WORK[ 0 ] => 96
*/
function dormbr( order, vect, side, trans, M, N, K, A, LDA, TAU, C, LDC, WORK, LWORK ) {
	var applyq;
	var sa1;
	var sa2;
	var sc1;
	var sc2;
	var nq;

	if ( !isLayout( order ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a valid order. Value: `%s`.', order ) );
	}
	if ( vect !== 'Q' && vect !== 'P' ) {
		throw new TypeError( format( 'invalid argument. Second argument must be either `\'Q\'` or `\'P\'`. Value: `%s`.', vect ) );
	}
	if ( !isOperationSide( side ) ) {
		throw new TypeError( format( 'invalid argument. Third argument must be a valid operation side. Value: `%s`.', side ) );
	}
	if ( !isMatrixTranspose( trans ) ) {
		throw new TypeError( format( 'invalid argument. Fourth argument must be a valid transpose operation. Value: `%s`.', trans ) );
	}
	if ( M < 0 ) {
		throw new RangeError( format( 'invalid argument. Fifth argument must be a nonnegative integer. Value: `%d`.', M ) );
	}
	if ( N < 0 ) {
		throw new RangeError( format( 'invalid argument. Sixth argument must be a nonnegative integer. Value: `%d`.', N ) );
	}
	if ( K < 0 ) {
		throw new RangeError( format( 'invalid argument. Seventh argument must be a nonnegative integer. Value: `%d`.', K ) );
	}
	applyq = ( vect === 'Q' );
	if ( side === 'left' ) {
		nq = M;
		if ( ( !isRowMajor( order ) ) && LDA < max( 1, ( ( applyq ) ? nq : min( nq, K ) ) ) ) {
			if ( applyq ) {
				throw new RangeError( format( 'invalid argument. Ninth argument must be greater than or equal to `max(1,NQ)`. Value: `%d`.', LDA ) );
			}
			throw new RangeError( format( 'invalid argument. Ninth argument must be greater than or equal to `max(1,min(NQ,K))`. Value: `%d`.', LDA ) );
		}
		if ( isRowMajor( order ) && LDA < max( 1, K ) ) {
			throw new RangeError( format( 'invalid argument. Ninth argument must be greater than or equal to `max(1,K)`. Value: `%d`.', LDA ) );
		}
		if ( LWORK < max( 1, N ) && LWORK !== -1 ) {
			throw new RangeError( format( 'invalid argument. Fourteenth argument must be greater than or equal to `max(1, N)` when `SIDE = \'left\'`. Value: `%d`.', LWORK ) );
		}
	} else {
		nq = N;
		if ( ( !isRowMajor( order ) ) && LDA < max( 1, ( ( applyq ) ? nq : min( nq, K ) ) ) ) {
			if ( applyq ) {
				throw new RangeError( format( 'invalid argument. Ninth argument must be greater than or equal to `max(1,NQ)`. Value: `%d`.', LDA ) );
			}
			throw new RangeError( format( 'invalid argument. Ninth argument must be greater than or equal to `max(1,min(NQ,K))`. Value: `%d`.', LDA ) );
		}
		if ( isRowMajor( order ) && LDA < max( 1, K ) ) {
			throw new RangeError( format( 'invalid argument. Ninth argument must be greater than or equal to `max(1,K)`. Value: `%d`.', LDA ) );
		}
		if ( LWORK < max( 1, M ) && LWORK !== -1 ) {
			throw new RangeError( format( 'invalid argument. Fourteenth argument must be greater than or equal to `max(1, M)` when `SIDE = \'right\'`. Value: `%d`.', LWORK ) );
		}
	}
	if ( isRowMajor( order ) ) {
		if ( LDC < max( 1, N ) ) {
			throw new RangeError( format( 'invalid argument. Twelfth argument must be greater than or equal to `max(1,N)`. Value: `%d`.', LDC ) );
		}
	} else if ( LDC < max( 1, M ) ) {
		throw new RangeError( format( 'invalid argument. Twelfth argument must be greater than or equal to `max(1,M)`. Value: `%d`.', LDC ) );
	}
	if ( order === 'column-major' ) {
		sa1 = 1;
		sa2 = LDA;
		sc1 = 1;
		sc2 = LDC;
	} else {
		sa1 = LDA;
		sa2 = 1;
		sc1 = LDC;
		sc2 = 1;
	}
	return base( vect, side, trans, M, N, K, A, sa1, sa2, 0, TAU, 1, 0, C, sc1, sc2, 0, WORK, 1, 0, LWORK );
}


// EXPORTS //

module.exports = dormbr;
